"use client";

import { Canvas, useFrame, useThree, type ThreeEvent } from "@react-three/fiber";
import { useGLTF } from "@react-three/drei";
import { useEffect, useMemo, useRef, useState, type RefObject } from "react";
import * as THREE from "three";
import { islandLandmarks, type LandmarkId } from "@/content/island";
import { canStand, findPath, loadNav, nearestWalkable, toCell, toPoint, type NavGrid, type Point } from "@/lib/island/nav";
import { ToyWorld } from "@/lib/island/toyPhysics";
import { IslandFolio, SEAT_HEIGHT, type WalkerState } from "./IslandFolio";

// Generated by art/island/build_island.py, exported by export_island.py with meshopt compression.
const ISLAND_URL = "/playground/island.glb";
// Both views look from the south-east and above, like the Blender preview camera.
const VIEW = new THREE.Vector3(1, 0.82, 1).normalize();
const OVERVIEW_TARGET = new THREE.Vector3(0, -1.5, 1.5);
const SPEED = 3.4;         // m/s
const NEAR = 1.7;          // how close to a landmark's ring counts as arriving (m)
const FIRE_NEAR = 2.6;     // walking this close lights the campfire
const PLANE_NEAR = 1.7;    // walking this close collects a paper plane (some float just off the walkable edge)
const DOWN = new THREE.Vector3(0, -1, 0);
const STEP = 0.45;        // the highest step Folio walks up
const DECK_REACH = 1.2;   // a deck above Folio within this always wins (see floorY)
const REGROUND = 1.0;     // first frame or getting up: look for the floor from this far above (not onto a rail)

export type Mode = "overview" | "walk";

export type SceneProps = {
  mode: Mode;
  /** A click or tap on the island while in the overview: start walking. */
  onWalkStart: () => void;
  selected: LandmarkId | null;
  hovered: LandmarkId | null;
  onSelect: (id: LandmarkId) => void;
  onHover: (id: LandmarkId | null) => void;
  /** Walk to a landmark (from the list under the island); n changes on every request. */
  goTo: { id: LandmarkId; n: number } | null;
  /** The landmark Folio is standing at, or null. */
  onNear: (id: LandmarkId | null) => void;
  /** Folio sat down on a bench (true) or got up (false). */
  onSit: (sitting: boolean) => void;
  /** Paper planes already found (indices into planeFacts), and a new find. */
  collected: ReadonlySet<number>;
  onCollect: (index: number) => void;
  /** The campfire has been lit this session, and the moment it is. */
  fireLit: boolean;
  onFireLit: () => void;
  /** All planes found: Folio cheers (performance.now() until). */
  cheerUntil: number;
  /** The pointer is over the island, so the keys steer Folio. */
  keysActive: boolean;
  /** Label elements drawn by IslandPiece over the canvas; the scene moves them to their landmarks each frame. */
  labels: RefObject<Map<LandmarkId, HTMLElement>>;
  /** The page background, for the fog that fades the island's edge while walking. */
  fogColor: string;
};

type Mark = { id: LandmarkId; top: THREE.Vector3; door: THREE.Vector3 };
// Benches seat two side by side (BENCH_SEATS in build_island.py; a seated Folio is about 1 m wide): the visitor
// takes the first seat, the other is for another visitor once the island is shared.
const BENCH_SEATS = [-0.52, 0.52];
type Bench = { pos: THREE.Vector3; front: THREE.Vector3; right: THREE.Vector3; seats: THREE.Vector3[]; approach: THREE.Vector3; yaw: number; mine: number; boat?: boolean };
type Plane = { index: number; obj: THREE.Object3D; base: THREE.Vector3 };

/** Blender's exporter names a multi-material mesh's parts after the object; walk up to the named node. */
function nameOf(o: THREE.Object3D) {
  let n: THREE.Object3D | null = o;
  while (n && !n.name) n = n.parent;
  return n?.name ?? "";
}

const KEYS: Record<string, [number, number]> = {
  KeyW: [0, 1], ArrowUp: [0, 1], KeyS: [0, -1], ArrowDown: [0, -1],
  KeyA: [-1, 0], ArrowLeft: [-1, 0], KeyD: [1, 0], ArrowRight: [1, 0],
};

const SPARKS = 28;

function World(props: SceneProps) {
  const { mode, onWalkStart, selected, hovered, onSelect, onHover, goTo, onNear, onSit, collected, onCollect, fireLit, onFireLit, cheerUntil, keysActive, labels } = props;
  const { scene } = useGLTF(ISLAND_URL, false, true);
  const invalidate = useThree((s) => s.invalidate);
  const gl = useThree((s) => s.gl);

  // ---- the island, its landmarks and things to use, the surfaces you can stand on, the spawn point
  const island = useMemo(() => {
    const root = scene.clone(true);
    const floors: THREE.Object3D[] = [];
    root.traverse((o) => {
      const mesh = o as THREE.Mesh;
      if (!mesh.isMesh) return;
      const name = nameOf(o);
      const flat = /^(walk_ground|walk_path|water_pond|island_base|deco_(path|paving|grass|lilies|photo_spot))/.test(name);
      mesh.castShadow = !flat;
      mesh.receiveShadow = true;
      // Floors: the ground, the paths and each deck's flat top (walk_deck_*, gap-free and a little wider than the
      // planks; hidden). The visible dock and lookout (planks, rails, posts) are only looked at.
      if (/^walk_deck_/.test(name)) mesh.visible = false;
      if (/^walk_/.test(name) && !/^walk_(dock|lookout)/.test(name)) floors.push(mesh);
    });
    root.updateMatrixWorld(true);
    const decks = new Set<THREE.Object3D>(floors.filter((f) => /^walk_deck_/.test(nameOf(f))));

    const marks: Mark[] = [];
    for (const l of islandLandmarks) {
      const obj = root.getObjectByName(l.object);
      const door = root.getObjectByName(l.door);
      if (!obj || !door) {
        if (process.env.NODE_ENV !== "production") console.warn(`Island: missing ${!obj ? l.object : l.door} in ${ISLAND_URL}`);
        continue;
      }
      obj.traverse((c) => (c.userData.landmark = l.id));
      const box = new THREE.Box3().setFromObject(obj);
      marks.push({
        id: l.id,
        top: new THREE.Vector3((box.min.x + box.max.x) / 2, box.max.y + 1.0, (box.min.z + box.max.z) / 2),
        door: door.getWorldPosition(new THREE.Vector3()),
      });
    }

    // Benches: you sit facing the way the bench faces (Blender's local -Y is three's local +Z).
    const benches: Bench[] = [];
    const q = new THREE.Quaternion();
    root.children.forEach((o) => {
      if (!/^block_bench_\d+$/.test(o.name)) return;
      const pos = o.getWorldPosition(new THREE.Vector3());
      const front = new THREE.Vector3(0, 0, 1).applyQuaternion(o.getWorldQuaternion(q)).setY(0).normalize();
      const right = new THREE.Vector3(1, 0, 0).applyQuaternion(q).setY(0).normalize();
      const seats = BENCH_SEATS.map((u) => pos.clone().addScaledVector(right, u));
      const index = benches.length;
      o.traverse((c) => (c.userData.bench = index));
      benches.push({ pos, front, right, seats, approach: pos.clone().addScaledVector(front, 0.95), yaw: Math.atan2(front.x, front.z), mine: 0 });
    });

    // Campfire: its flame meshes grow when it is lit.
    const fireObj = root.getObjectByName("block_campfire");
    const fire = fireObj ? fireObj.getWorldPosition(new THREE.Vector3()) : null;
    const flames: THREE.Mesh[] = [];
    fireObj?.traverse((c) => {
      const m = c as THREE.Mesh;
      const mat = m.material as THREE.Material | undefined;
      if (m.isMesh && mat && /^(flame|lamp_glow)$/.test(mat.name)) flames.push(m);
    });
    fireObj?.traverse((c) => (c.userData.fire = true));

    // Paper planes, in name order (collect_plane_01..).
    const planes: Plane[] = root.children
      .filter((o) => /^collect_plane_\d+$/.test(o.name))
      .sort((a, b) => a.name.localeCompare(b.name))
      .map((obj, index) => ({ index, obj, base: obj.position.clone() }));

    // The rowboat is a seat too: climb in from the dock, sit on the stern seat facing the bow. Its seats are
    // at local x -0.55 and 0.4, about 0.35 above the boat's origin (Blender's local X stays three's local X).
    const boatObj = root.getObjectByName("deco_boat");
    if (boatObj) {
      const pos = boatObj.getWorldPosition(new THREE.Vector3());
      const bq = boatObj.getWorldQuaternion(new THREE.Quaternion());
      const front = new THREE.Vector3(1, 0, 0).applyQuaternion(bq).setY(0).normalize();
      const right = new THREE.Vector3(-front.z, 0, front.x);
      const seats = [-0.55, 0.4].map((u) => pos.clone().addScaledVector(front, u).setY(pos.y + 0.35 - SEAT_HEIGHT));
      const index = benches.length;
      boatObj.traverse((c) => (c.userData.bench = index));
      benches.push({ pos, front, right, seats, approach: pos.clone(), yaw: Math.atan2(front.x, front.z), mine: 0, boat: true });
    }

    const spawn = root.getObjectByName("spawn")?.getWorldPosition(new THREE.Vector3()) ?? new THREE.Vector3();
    const toys = root.children.filter((o) => /^phys_/.test(o.name));
    return { root, marks, floors, decks, spawn, benches, fire, flames, planes, toys };
  }, [scene]);
  const { root, marks, benches, fire } = island;
  // Effects and frames reach the island through this ref: they move its objects, which render must not.
  const live = useRef(island);
  useEffect(() => {
    live.current = island;
  }, [island]);

  // ---- the walk grid
  const nav = useRef<NavGrid | null>(null);
  useEffect(() => {
    let live = true;
    loadNav().then((g) => live && (nav.current = g)).catch((e) => console.warn(e));
    return () => {
      live = false;
    };
  }, []);

  // ---- Folio's state, its route, what it's doing, and the keys held
  const walker = useRef<WalkerState>({ pos: island.spawn.clone(), yaw: Math.PI, speed: 0, sit: 0, cheerUntil: 0 });
  useEffect(() => {
    walker.current.cheerUntil = cheerUntil;
    invalidate();
  }, [cheerUntil, invalidate]);
  const route = useRef<Point[]>([]);
  const keys = useRef(new Set<string>());
  const near = useRef<LandmarkId | null>(null);
  const [nearId, setNearId] = useState<LandmarkId | null>(null);
  const seat = useRef<{ pending: number | null; on: number | null }>({ pending: null, on: null });
  const marker = useRef<THREE.Mesh>(null);
  const markerLife = useRef(0);
  const fireLight = useRef<THREE.PointLight>(null);
  const sparks = useRef<THREE.Points>(null);
  const smoke = useRef<THREE.Group>(null);
  const fireOn = useRef(fireLit);
  useEffect(() => {
    if (fireLit) fireOn.current = true;   // lit earlier this visit
    invalidate();
  }, [fireLit, invalidate]);
  const got = useRef(new Set(collected));
  const leaving = useRef<number[]>([]);              // per plane: 0 waiting, (0, 1) flying away, 1 gone
  const boatStep = useRef<Point | null>(null);      // the dock spot next to the boat
  const toys = useRef<ToyWorld | null>(null);
  const reground = useRef(true);                     // first frame, or just got up: find the floor from above
  // Scratch objects reused every frame (kept in a ref: they are mutated outside render).
  const scratch = useRef({
    ray: new THREE.Raycaster(), probe: new THREE.Vector3(), fwd: new THREE.Vector3(), right: new THREE.Vector3(),
    v: new THREE.Vector3(), desiredPos: new THREE.Vector3(), desiredLook: new THREE.Vector3(),
    lookAt: OVERVIEW_TARGET.clone(), placed: false, fire: 0, idle: 0,
  });

  // Knock-over props: a toy physics world over the phys_* objects.
  useEffect(() => {
    const w = new ToyWorld();
    for (const o of island.toys) w.add(o);
    toys.current = w;
    return () => {
      toys.current = null;
    };
  }, [island]);

  // Planes found earlier (saved in the browser) start hidden.
  useEffect(() => {
    for (const p of live.current.planes) {
      if (collected.has(p.index) && !got.current.has(p.index)) got.current.add(p.index);
      const l = leaving.current[p.index] ?? 0;
      if (got.current.has(p.index) && !(l > 0 && l < 1)) p.obj.scale.setScalar(0);
    }
    invalidate();
  }, [collected, island, invalidate]);

  /**
   * The height of the floor under (x, z): the highest surface no more than a step above where Folio is now.
   * A deck's flat top (walk_deck_*, gap-free, wider than the planks) wins from further below too: nothing walkable
   * is under a deck, so if Folio is ever beneath one, it comes up onto it instead of walking under the planks.
   */
  const floorY = (x: number, z: number, from: number) => {
    const { ray, probe } = scratch.current;
    probe.set(x, from + 4, z);
    ray.set(probe, DOWN);
    for (const hit of ray.intersectObjects(live.current.floors, false)) {
      if (hit.point.y <= from + (live.current.decks.has(hit.object) ? DECK_REACH : STEP)) return hit.point.y;
    }
    return from;
  };

  const standUp = () => {
    if (seat.current.on !== null) {
      reground.current = true;
      seat.current.on = null;
      onSit(false);
    }
    seat.current.pending = null;
  };

  const walkTo = (dest: Point, showMarker = true) => {
    const g = nav.current;
    if (!g) return;
    standUp();
    const path = findPath(g, { x: walker.current.pos.x, z: walker.current.pos.z }, dest);
    route.current = path;
    const end = path[path.length - 1];
    if (end && marker.current && showMarker) {
      marker.current.position.set(end.x, floorY(end.x, end.z, walker.current.pos.y + 0.3) + 0.08, end.z);
      markerLife.current = 1;
    }
    invalidate();
  };

  // Development only: a handle for testing the interactions without aiming clicks at small objects.
  useEffect(() => {
    if (process.env.NODE_ENV === "production") return;
    const w = window as unknown as { __island?: unknown };
    w.__island = {
      benches: () => live.current.benches.length,
      sit: (i: number) => {
        const b = live.current.benches[i];
        if (!b) return;
        let ap: Point = { x: b.approach.x, z: b.approach.z };
        const g = nav.current;
        if (b.boat && g) {
          const c = nearestWalkable(g, toCell(g, ap));
          if (c) ap = toPoint(g, c);
          boatStep.current = ap;
        }
        walkTo(ap, false);
        seat.current.pending = i;
      },
      goto: (x: number, z: number) => walkTo({ x, z }),
      walkableCells: () => nav.current?.rows.reduce((n, r) => n + r.split("1").length - 1, 0) ?? 0,
      toys: () => toys.current?.bodies.map((b) => ({ name: b.obj.name, awake: b.awake, x: +b.pos.x.toFixed(2), y: +b.pos.y.toFixed(2), z: +b.pos.z.toFixed(2), home: +b.pos.distanceTo(b.home.pos).toFixed(2) })) ?? [],
      state: () => ({ x: walker.current.pos.x, y: walker.current.pos.y, z: walker.current.pos.z, sit: walker.current.sit, seated: seat.current.on }),
      // The floor rule itself: where Folio would stand at (x, z), coming from height y.
      floorAt: (x: number, z: number, y: number) => floorY(x, z, y),
      decks: () => [...live.current.decks].map((o) => nameOf(o)),
      // Every floor surface under (x, z), top first: name and height.
      floors: (x: number, z: number) => {
        const r = new THREE.Raycaster(new THREE.Vector3(x, 20, z), DOWN);
        return r.intersectObjects(live.current.floors, false).map((h) => [nameOf(h.object), +h.point.y.toFixed(3)]);
      },
    };
    return () => {
      delete w.__island;
    };
    // walkTo reads refs only.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // A landmark picked from the list: walk to its door.
  useEffect(() => {
    if (!goTo) return;
    const m = marks.find((k) => k.id === goTo.id);
    if (m) walkTo({ x: m.door.x, z: m.door.z });
    // walkTo reads refs only; re-run on each new request.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [goTo, marks]);

  // Keys steer Folio while the pointer is over the island and walking has started.
  useEffect(() => {
    const held = keys.current;
    if (!keysActive || mode !== "walk") {
      held.clear();
      return;
    }
    const down = (e: KeyboardEvent) => {
      if (!(e.code in KEYS) || (e.target as HTMLElement)?.closest?.("input, textarea, select, [contenteditable]")) return;
      e.preventDefault();
      held.add(e.code);
      invalidate();
    };
    const up = (e: KeyboardEvent) => held.delete(e.code);
    window.addEventListener("keydown", down);
    window.addEventListener("keyup", up);
    return () => {
      window.removeEventListener("keydown", down);
      window.removeEventListener("keyup", up);
      held.clear();
    };
  }, [keysActive, mode, invalidate]);

  // While walking, the little things keep moving (planes, fire, breathing) at about 30 frames a second,
  // and only while the island is on screen.
  useEffect(() => {
    if (mode !== "walk") return;
    let raf = 0, last = 0, visible = true;
    const io = new IntersectionObserver(([e]) => (visible = e.isIntersecting));
    io.observe(gl.domElement);
    const tick = (now: number) => {
      raf = requestAnimationFrame(tick);
      if (visible && now - last > 33) {
        last = now;
        invalidate();
      }
    };
    raf = requestAnimationFrame(tick);
    return () => {
      cancelAnimationFrame(raf);
      io.disconnect();
    };
  }, [mode, gl, invalidate]);

  useEffect(() => invalidate(), [mode, selected, hovered, invalidate]);

  // Spark and smoke particles for the lit campfire.
  const sparkGeo = useMemo(() => {
    const g = new THREE.BufferGeometry();
    g.setAttribute("position", new THREE.Float32BufferAttribute(new Float32Array(SPARKS * 3), 3));
    return g;
  }, []);
  const sparkSeeds = useMemo(() => Array.from({ length: SPARKS }, (_, k) => ({ a: (k * 2.39996) % (Math.PI * 2), r: 0.1 + ((k * 0.37) % 0.3), s: 0.6 + ((k * 0.61) % 0.8), o: (k * 0.173) % 1 })), []);

  useFrame((state, delta) => {
    const { camera, size, clock } = state;
    const { marks, benches, fire, flames, planes } = live.current;
    const tmp = scratch.current;
    const dt = Math.min(delta, 1 / 30);
    const t = clock.elapsedTime;
    const w = walker.current;
    const g = nav.current;
    let busy = false;
    const aspect = size.width / Math.max(size.height, 1);
    const overviewDist = aspect >= 1.5 ? 70 : aspect >= 1.1 ? 82 : aspect >= 0.8 ? 104 : 130;
    const walkDist = aspect >= 1.1 ? 19 : aspect >= 0.8 ? 23 : 28;

    // ---- movement: keys first (relative to the camera), else the route
    let dx = 0, dz = 0;
    if (keys.current.size && mode === "walk") {
      let kx = 0, ky = 0;
      keys.current.forEach((c) => {
        kx += KEYS[c][0];
        ky += KEYS[c][1];
      });
      if (kx || ky) {
        route.current = [];
        standUp();
        camera.getWorldDirection(tmp.fwd).setY(0).normalize();
        tmp.right.crossVectors(tmp.fwd, camera.up).normalize();
        tmp.v.copy(tmp.fwd).multiplyScalar(ky).addScaledVector(tmp.right, kx).normalize();
        dx = tmp.v.x;
        dz = tmp.v.z;
      }
    } else if (route.current.length) {
      const next = route.current[0];
      const ex = next.x - w.pos.x, ez = next.z - w.pos.z, d = Math.hypot(ex, ez);
      if (d < 0.12) {
        route.current.shift();
      } else {
        dx = ex / d;
        dz = ez / d;
      }
    }
    // Off the walkable area (just up from a bench, out of the boat): walk straight to the nearest walkable spot
    // first, ignoring the keys and the route until then, so Folio can never wander across the water.
    let escaping = false;
    if (g && seat.current.on === null && !canStand(g, { x: w.pos.x, z: w.pos.z })) {
      const c = nearestWalkable(g, toCell(g, { x: w.pos.x, z: w.pos.z }));
      if (c) {
        const p = toPoint(g, c), ex = p.x - w.pos.x, ez = p.z - w.pos.z, d = Math.hypot(ex, ez);
        if (d > 0.02) {
          dx = ex / d;
          dz = ez / d;
          escaping = true;
        }
      }
    }
    const moving = dx !== 0 || dz !== 0;
    w.speed = THREE.MathUtils.damp(w.speed, moving ? SPEED : 0, 10, dt);
    if (moving && g) {
      const step = w.speed * dt;
      const nx = w.pos.x + dx * step, nz = w.pos.z + dz * step;
      if (escaping || canStand(g, { x: nx, z: nz })) w.pos.set(nx, w.pos.y, nz);
      else if (canStand(g, { x: nx, z: w.pos.z })) w.pos.setX(nx);       // slide along walls
      else if (canStand(g, { x: w.pos.x, z: nz })) w.pos.setZ(nz);
      else route.current = [];
      let turn = Math.atan2(dx, dz) - w.yaw;
      turn = Math.atan2(Math.sin(turn), Math.cos(turn));
      w.yaw += turn * Math.min(1, dt * 12);
      busy = true;
    }
    if (w.speed > 0.02) busy = true;

    // ---- benches: arrive, turn and sit; seated, settle onto the seat
    const sc = seat.current;
    if (sc.pending !== null && !route.current.length && !moving) {
      const b = benches[sc.pending];
      const ap = b.boat && boatStep.current ? boatStep.current : b.approach;
      if (Math.hypot(ap.x - w.pos.x, ap.z - w.pos.z) < 0.5) {
        sc.on = sc.pending;
        onSit(true);
      }
      sc.pending = null;
    }
    if (sc.on !== null) {
      const b = benches[sc.on]; const seatPos = b.seats[b.mine];
      const kk = 1 - Math.exp(-6 * dt);
      w.pos.x += (seatPos.x - w.pos.x) * kk;
      w.pos.z += (seatPos.z - w.pos.z) * kk;
      w.pos.y += (seatPos.y - w.pos.y) * kk;
      let turn = b.yaw - w.yaw;
      turn = Math.atan2(Math.sin(turn), Math.cos(turn));
      w.yaw += turn * kk;
    } else {
      w.pos.y = floorY(w.pos.x, w.pos.z, reground.current ? w.pos.y + REGROUND : w.pos.y);
      reground.current = false;
    }
    const sitTarget = sc.on !== null ? 1 : 0;
    w.sit += (sitTarget - w.sit) * (1 - Math.exp(-8 * dt));
    if (Math.abs(w.sit - sitTarget) > 0.01) busy = true;
    if (performance.now() < w.cheerUntil) busy = true;

    // ---- standing still for a moment, Folio turns to face you
    if (!moving && sc.on === null && sc.pending === null && w.speed < 0.05) {
      tmp.idle += dt;
      if (tmp.idle > 0.5 && mode === "walk") {
        let turn = Math.atan2(camera.position.x - w.pos.x, camera.position.z - w.pos.z) - w.yaw;
        turn = Math.atan2(Math.sin(turn), Math.cos(turn));
        if (Math.abs(turn) > 0.01) {
          w.yaw += turn * (1 - Math.exp(-4 * dt));
          busy = true;
        }
      }
    } else {
      tmp.idle = 0;
    }

    // ---- arriving at a landmark
    let at: LandmarkId | null = null;
    for (const m of marks) if (Math.hypot(m.door.x - w.pos.x, m.door.z - w.pos.z) < NEAR) at = m.id;
    if (at !== near.current) {
      near.current = at;
      setNearId(at);
      onNear(at);
    }

    // ---- campfire: embers until Folio walks up, then a fire with light, sparks and smoke
    if (fire) {
      if (!fireOn.current && mode === "walk" && Math.hypot(fire.x - w.pos.x, fire.z - w.pos.z) < FIRE_NEAR) {
        fireOn.current = true;
        onFireLit();
      }
      tmp.fire += ((fireOn.current ? 1 : 0) - tmp.fire) * (1 - Math.exp(-2.5 * dt));
      const f = tmp.fire;
      const flicker = 1 + f * (0.12 * Math.sin(t * 13) + 0.08 * Math.sin(t * 7.3 + 1));
      for (const m of flames) m.scale.set(0.45 + 0.85 * f * flicker, 0.35 + 1.15 * f * flicker, 0.45 + 0.85 * f * flicker);
      if (fireLight.current) fireLight.current.intensity = f * (5 + Math.sin(t * 11) * 0.8);
      if (sparks.current) {
        sparks.current.visible = f > 0.05;
        const pos = sparkGeo.getAttribute("position") as THREE.BufferAttribute;
        sparkSeeds.forEach((s, k) => {
          const life = (t * s.s + s.o) % 1;
          pos.setXYZ(k, fire.x + Math.cos(s.a + life * 3) * s.r * (1 + life), fire.y + 0.4 + life * 2.2, fire.z + Math.sin(s.a + life * 3) * s.r * (1 + life));
        });
        pos.needsUpdate = true;
        (sparks.current.material as THREE.PointsMaterial).opacity = f;
      }
      if (smoke.current) {
        smoke.current.visible = f > 0.05;
        smoke.current.children.forEach((puff, k) => {
          const life = (t * 0.25 + k / smoke.current!.children.length) % 1;
          puff.position.set(fire.x + Math.sin(t * 0.7 + k) * 0.3 * life, fire.y + 1.2 + life * 3.2, fire.z + life * 0.6);
          puff.scale.setScalar(0.25 + life * 0.7);
          ((puff as THREE.Mesh).material as THREE.MeshBasicMaterial).opacity = f * 0.35 * (1 - life);
        });
      }
    }

    // ---- paper planes: bob and turn; walk into one to collect it
    for (const p of planes) {
      if (got.current.has(p.index)) {
        const l = leaving.current[p.index] ?? 1;
        if (l > 0 && l < 1) {                    // flying away after being found
          const nl = Math.min(1, l + dt * 1.2);
          leaving.current[p.index] = nl;
          p.obj.position.setY(p.obj.position.y + dt * (2 + nl * 4));
          p.obj.rotateY(dt * 8);
          p.obj.scale.setScalar(1 - nl);
          busy = true;
        }
        continue;
      }
      p.obj.position.set(p.base.x, p.base.y + Math.sin(t * 2 + p.index) * 0.12, p.base.z);
      p.obj.rotateY(dt * 0.9);
      if (mode === "walk" && Math.hypot(p.base.x - w.pos.x, p.base.z - w.pos.z) < PLANE_NEAR && Math.abs(p.base.y - w.pos.y) < 2) {
        got.current.add(p.index);
        leaving.current[p.index] = 0.001;
        onCollect(p.index);
        busy = true;
      }
    }

    // ---- the destination marker fades out
    if (marker.current) {
      markerLife.current = Math.max(0, markerLife.current - dt * 1.2);
      const mat = marker.current.material as THREE.MeshBasicMaterial;
      mat.opacity = markerLife.current;
      marker.current.visible = markerLife.current > 0;
      marker.current.scale.setScalar(1 + (1 - markerLife.current) * 0.5);
      if (markerLife.current > 0) busy = true;
    }

    // ---- camera: the overview, following Folio, or a seated view over the bench
    const { desiredPos, desiredLook, lookAt } = tmp;
    if (mode === "walk" && sc.on !== null) {
      const b = benches[sc.on];
      // In front of the bench, a little to one side, looking at Folio: you see its face, not its back.
      const seatPos = b.seats[b.mine];
      desiredLook.copy(seatPos).setY(seatPos.y + 0.8);
      desiredPos.copy(seatPos).addScaledVector(b.front, 4.6).addScaledVector(b.right, 1.5).setY(seatPos.y + 2.0);
    } else if (mode === "walk") {
      desiredLook.set(w.pos.x, w.pos.y + 0.8, w.pos.z);
      desiredPos.copy(desiredLook).addScaledVector(VIEW, walkDist);
    } else {
      desiredLook.copy(OVERVIEW_TARGET);
      desiredPos.copy(OVERVIEW_TARGET).addScaledVector(VIEW, overviewDist);
    }
    if (!tmp.placed) {
      camera.position.copy(desiredPos);
      lookAt.copy(desiredLook);
      tmp.placed = true;
    }
    const k = 1 - Math.exp(-3.2 * dt);
    camera.position.lerp(desiredPos, k);
    lookAt.lerp(desiredLook, k);
    camera.lookAt(lookAt);
    if (camera.position.distanceTo(desiredPos) > 0.02 || lookAt.distanceTo(desiredLook) > 0.02) busy = true;

    // Fog fades the island's edge into the page while walking; none in the overview.
    const fog = state.scene.fog as THREE.Fog | null;
    if (fog) {
      const seated = sc.on !== null;
      const near_ = mode === "walk" ? (seated ? 30 : walkDist + 10) : 400, far = mode === "walk" ? (seated ? 70 : walkDist + 42) : 800;
      fog.near += (near_ - fog.near) * k;
      fog.far += (far - fog.far) * k;
    }

    // Labels follow their landmarks.
    const els = labels.current;
    if (els) {
      for (const m of marks) {
        const el = els.get(m.id);
        if (!el) continue;
        tmp.v.copy(m.top).project(camera);
        const off = tmp.v.z > 1 || Math.abs(tmp.v.x) > 1.1 || Math.abs(tmp.v.y) > 1.1;
        el.style.transform = `translate(-50%, -50%) translate(${((tmp.v.x + 1) / 2) * size.width}px, ${((1 - tmp.v.y) / 2) * size.height}px)`;
        el.style.opacity = off ? "0" : "1";
      }
    }

    // ---- knock-over props
    if (toys.current) {
      const pusher = mode === "walk" && w.sit < 0.5
        ? { x: w.pos.x, y: w.pos.y, z: w.pos.z, vx: Math.sin(w.yaw) * w.speed, vz: Math.cos(w.yaw) * w.speed, radius: 0.42 }
        : null;
      const moved = toys.current.step(
        dt,
        pusher,
        (x, z) => floorY(x, z, 6),
        (x, z) => (g ? !canStand(g, { x, z }) : false),
      );
      if (moved) busy = true;
    }

    if (busy) invalidate();
  });

  const pickOf = (e: ThreeEvent<PointerEvent | MouseEvent>) => {
    const u = e.object.userData as { landmark?: LandmarkId; bench?: number; fire?: boolean };
    return u;
  };
  const active = hovered ?? selected;

  return (
    <>
      <primitive
        object={root}
        onPointerMove={(e: ThreeEvent<PointerEvent>) => {
          const u = pickOf(e);
          onHover(u.landmark ?? null);
          document.body.style.cursor = u.landmark || u.bench !== undefined || u.fire ? "pointer" : mode === "walk" ? "crosshair" : "pointer";
        }}
        onPointerLeave={() => {
          onHover(null);
          document.body.style.cursor = "";
        }}
        onClick={(e: ThreeEvent<MouseEvent>) => {
          if (e.delta > 8) return; // a drag, not a click
          e.stopPropagation();
          if (mode === "overview") onWalkStart();
          const u = pickOf(e);
          if (u.landmark) {
            onSelect(u.landmark);
            const m = marks.find((k) => k.id === u.landmark);
            if (m) walkTo({ x: m.door.x, z: m.door.z });
          } else if (u.bench !== undefined && benches[u.bench]) {
            const b = benches[u.bench];
            if (seat.current.on === u.bench) return;
            let ap: Point = { x: b.approach.x, z: b.approach.z };
            const g = nav.current;
            if (b.boat && g) {
              const c = nearestWalkable(g, toCell(g, ap));
              if (c) ap = toPoint(g, c);
              boatStep.current = ap;
            }
            walkTo(ap, false);
            seat.current.pending = u.bench;
          } else if (u.fire && fire) {
            walkTo({ x: fire.x - 1.5, z: fire.z - 1.5 }); // the far side, so the fire stays in view
          } else {
            walkTo({ x: e.point.x, z: e.point.z });
          }
        }}
      />
      <IslandFolio walker={walker} />
      {marks.map((m) => {
        const on = m.id === active || m.id === nearId;
        return (
          <mesh key={m.id} position={[m.door.x, m.door.y + 0.12, m.door.z]} rotation={[-Math.PI / 2, 0, 0]} scale={on ? 1.25 : 1}>
            <ringGeometry args={[0.6, 0.82, 40]} />
            <meshBasicMaterial color="#ffffff" transparent opacity={on ? 1 : 0.65} />
          </mesh>
        );
      })}
      <mesh ref={marker} rotation={[-Math.PI / 2, 0, 0]} visible={false}>
        <ringGeometry args={[0.28, 0.42, 32]} />
        <meshBasicMaterial color="#ffffff" transparent opacity={0} depthWrite={false} />
      </mesh>
      {fire && (
        <>
          <pointLight ref={fireLight} position={[fire.x, fire.y + 0.9, fire.z]} color="#ff9a3c" intensity={0} distance={9} decay={1.6} />
          <points ref={sparks} geometry={sparkGeo} visible={false}>
            <pointsMaterial color="#ffc46b" size={0.09} transparent opacity={0} depthWrite={false} />
          </points>
          <group ref={smoke} visible={false}>
            {[0, 1, 2, 3, 4].map((k) => (
              <mesh key={k}>
                <icosahedronGeometry args={[0.5, 1]} />
                <meshBasicMaterial color="#cfc8bd" transparent opacity={0} depthWrite={false} />
              </mesh>
            ))}
          </group>
        </>
      )}
    </>
  );
}

export default function IslandScene(props: SceneProps) {
  const { onHover, fogColor } = props;
  return (
    <Canvas
      frameloop="demand"
      flat
      shadows
      dpr={[1, 2]}
      camera={{ fov: 30, near: 0.5, far: 400 }}
      gl={{ antialias: true, alpha: true }}
      onPointerLeave={() => {
        onHover(null);
        document.body.style.cursor = "";
      }}
      fallback={null}
    >
      <fog attach="fog" args={[fogColor, 400, 800]} />
      {/* Warm sky over green ground, and one low sun for long soft shadows, like the references. */}
      <hemisphereLight args={["#fff4e0", "#7d8f5c", 1.6]} />
      <directionalLight
        position={[26, 42, 14]}
        intensity={2.4}
        color="#fff1d6"
        castShadow
        shadow-mapSize={[2048, 2048]}
        shadow-camera-left={-30}
        shadow-camera-right={30}
        shadow-camera-top={30}
        shadow-camera-bottom={-30}
        shadow-camera-near={1}
        shadow-camera-far={120}
        shadow-bias={-0.0004}
        shadow-normalBias={0.05}
      />
      <World {...props} />
    </Canvas>
  );
}

useGLTF.preload(ISLAND_URL, false, true);
